Rewrite the following GNU C++17 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to rewrite:
<original_code>
#include<bits/stdc++.h>
#define LL long long
#define pb push_back
#define mp make_pair
#define pii pair<int,int>
using namespace std;
inline int read(){
	int v=0,f=1;
	char c=getchar();
	while (c<'0' || c>'9'){
		if (c=='-') f=-1;
		c=getchar();
	}
	while (c>='0' && c<='9'){
		v=v*10+c-'0';
		c=getchar();
	}
	return v*f;
}
const int Maxn=10;
const LL mod=1e9+7;
LL qp(LL x,LL p){
	LL ret=1;
	while (p){
		if (p&1) ret=ret*x%mod;
		x=x*x%mod;
		p>>=1; 
	}
	return ret;
}
LL inv(LL x){
	return qp(x,mod-2);
}
int p[Maxn][Maxn],n;
int id[64],ki,X[1048576],Y[1048576];
void add(int &x,int y){
	x+=y;
	if (x>=mod) x-=mod;
}
void sub(int &x,int y){
	x-=y;
	if (x<0) x+=mod;
}
void FWT(int *P,int opt)
{
	int N=1048576;
    for(int i=2;i<=N;i<<=1)
        for(int p=i>>1,j=0;j<N;j+=i)
            for(int k=j;k<j+p;++k)
                if (opt==1) add(P[k],P[k+p]);
                else sub(P[k],P[k+p]);
}
int main(){
	scanf("%d",&n);
	for (int i=0;i<n;i++){
		for (int j=0;j<n;j++){
			scanf("%d",&p[i][j]);
			p[i][j]=1ll*p[i][j]*inv(100)%mod;
		}
	}
	if (n<6){
		for (int i=n;i<6;i++){
			p[i][i]=1;
		}
		n=6;
	}
	int A=(1<<6)-1;
	for (int i=0;i<64;i++){
		if (__builtin_popcount(i)==3){
			id[i]=ki++;
		}
	}
	for (int i=0;i<(1<<18);i++){
		int msk1=i&A,msk2=i>>6&A,msk3=i>>12&A;
		int mask=0;
		LL pp=1;
		for (int j=0;j<6;j++){
			if (msk1>>j&1){
				pp=pp*p[0][j]%mod;
			}
			else{
				pp=pp*(mod+1-p[0][j])%mod;
			}
		}
		for (int j=0;j<6;j++){
			if (msk2>>j&1){
				pp=pp*p[1][j]%mod;
			}
			else{
				pp=pp*(mod+1-p[1][j])%mod;
			}
		}
		for (int j=0;j<6;j++){
			if (msk3>>j&1){
				pp=pp*p[2][j]%mod;
			}
			else{
				pp=pp*(mod+1-p[2][j])%mod;
			}
		}
		if (!p) continue;
		for (int a=0;a<6;a++){
			if (msk1>>a&1){
				for (int b=0;b<6;b++){
					if (a==b) continue;
					if (msk2>>b&1){
						for (int c=0;c<6;c++){
							if (a==c || b==c) continue;
							if (msk3>>c&1){
								int nmsk=(1<<a)|(1<<b)|(1<<c);
								mask|=1<<id[nmsk];
							}
						}
					}
				}
			}
		}
		add(X[mask],pp);
	}

	for (int i=0;i<(1<<18);i++){
		int msk1=i&A,msk2=i>>6&A,msk3=i>>12&A;
		int mask=0;
		LL pp=1;
		for (int j=0;j<6;j++){
			if (msk1>>j&1){
				pp=pp*p[3][j]%mod;
			}
			else{
				pp=pp*(mod+1-p[3][j])%mod;
			}
		}
		for (int j=0;j<6;j++){
			if (msk2>>j&1){
				pp=pp*p[4][j]%mod;
			}
			else{
				pp=pp*(mod+1-p[4][j])%mod;
			}
		}
		for (int j=0;j<6;j++){
			if (msk3>>j&1){
				pp=pp*p[5][j]%mod;
			}
			else{
				pp=pp*(mod+1-p[5][j])%mod;
			}
		}
		if (!p) continue;
		for (int a=0;a<6;a++){
			if (msk1>>a&1){
				for (int b=0;b<6;b++){
					if (a==b) continue;
					if (msk2>>b&1){
						for (int c=0;c<6;c++){
							if (a==c || b==c) continue;
							if (msk3>>c&1){
								int nmsk=(1<<a)|(1<<b)|(1<<c);
								nmsk^=A;
								mask|=1<<id[nmsk];
							}
						}
					}
				}
			}
		}
		add(Y[mask],pp);
	}
	FWT(X,1);
	FWT(Y,1);
	for (int i=0;i<1048576;i++){
		X[i]=1ll*X[i]*Y[i]%mod;
	}
	FWT(X,-1);
	int ans=0;
	for (int i=1;i<1048576;i++) add(ans,X[i]);
	printf("%d\n",ans);
	return 0;
}

